import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]
    # Ensure undirected and no self-loops
    for i in range(n):
        neighbors[i] = [j for j in neighbors[i] if j != i]
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
    # Handle trivial cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))
    # DSATUR with RLF fallback and Kempe refinement
    def dsatur():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        # Initial vertex: max degree
        v = max(range(n), key=lambda x: len(neighbors[x]))
        color[v] = 0
        for u in neighbors[v]:
            saturation[u].add(0)
        # Main loop
        for _ in range(1, n):
            # Find uncolored vertex with max saturation
            max_sat = -1
            candidates = []
            for v in range(n):
                if color[v] == -1:
                    sat = len(saturation[v])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                v = max(candidates, key=lambda x: sum(1 for y in neighbors[x] if color[y] == -1))
            else:
                v = candidates[0]
            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            # Update saturation of neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    saturation[u].add(c)
        return color
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any(w in S for w in neighbors[u])}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W
        return color
    # Try DSATUR first (usually fast and good)
    col_dsatur = dsatur()
    k_dsatur = max(col_dsatur) + 1 if n > 0 else 0
    # Try RLF (might be better on dense graphs)
    col_rlf = rlf()
    k_rlf = max(col_rlf) + 1 if n > 0 else 0
    # Choose the better initial coloring
    if k_dsatur <= k_rlf:
        color = col_dsatur[:]
        k = k_dsatur
    else:
        color = col_rlf[:]
        k = k_rlf
    # Kempe chain refinement to reduce color count
    improved = True
    while improved and k > 1:
        improved = False
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if color[v] == target_color]
        random.shuffle(vertices)  # randomize order to avoid worst-case
        for v in vertices:
            # Try to recolor v to a smaller color
            neighbor_colors = {color[u] for u in neighbors[v]}
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct recolor possible
                    color[v] = c
                    improved = True
                    break
            if improved:
                # After recoloring, check if target_color is still used
                if target_color not in color:
                    k -= 1
                    break
                else:
                    continue
            # Try Kempe chains
            for c in range(target_color):
                if c in neighbor_colors:
                    continue  # skip if neighbor already has color c (would cause conflict)
                # Find the Kempe chain component of v for colors (target_color, c)
                # We want to swap colors in the component containing v if it does not contain any vertex of color c
                # that is adjacent to v? Actually, we need to check if swapping removes v from target_color without
                # adding any vertex to target_color.
                # Standard: if the Kempe chain component of v in colors {target_color, c} does not contain any neighbor of v
                # with color c, then swapping will free target_color for v.
                # But simpler: if the component does not contain any vertex of color c that is adjacent to v,
                # then after swap, v becomes c and no neighbor becomes target_color.
                # Actually, we can just check: if there is no path from v to any vertex of color c using only colors
                # target_color and c, then swapping the component of v will not introduce color c to any neighbor of v.
                # Because if a neighbor of v had color c, it would be in the component.
                # So we do BFS/DFS on the subgraph induced by colors target_color and c.
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    x = stack.pop()
                    if x in visited:
                        continue
                    visited.add(x)
                    component.add(x)
                    for y in neighbors[x]:
                        if color[y] in (target_color, c) and y not in visited:
                            stack.append(y)
                # Check if any neighbor of v is in component and has color c
                conflict = False
                for y in neighbors[v]:
                    if y in component and color[y] == c:
                        conflict = True
                        break
                if not conflict:
                    # Perform swap: target_color <-> c in component
                    for x in component:
                        if color[x] == target_color:
                            color[x] = c
                        elif color[x] == c:
                            color[x] = target_color
                    improved = True
                    # After swap, v is now color c
                    break
            if improved:
                # Check if target_color is still used
                if target_color not in color:
                    k -= 1
                    break
                else:
                    continue
        # If we couldn't eliminate target_color, break
        if not improved:
            break
    return color
